/**
 * @file board_config.h
 *
 * @brief Board configuration of the board being built.
 *
 * This is the only header through which SEB modules (Application/,
 * Peripheral/, Services/) reach target hardware (architecture sections
 * 1.5.3 item 4, 2.6 rules 9-10 and 2.7; constitution Rule IV.C). It maps
 * each SEB_BOARD_* name to the handle or user label that the CubeMX
 * project generates. Pins are never written here as GPIOx / GPIO_PIN_n
 * literals: the .ioc stays the single source of every pin assignment.
 *
 * This file is hand-written. It is not generated by CubeMX and is not
 * touched by code regeneration.
 *
 * Current board: STM32F303VCT6 POC board.
 *
 * Porting to another board (for example the STM32F072RB test device or the
 * STM32F070CB production device):
 *  1. Create the CubeMX project for the device.
 *  2. Enable the debug USART in Asynchronous mode with its NVIC interrupt
 *     and no DMA (constitution V).
 *  3. Set Project Manager > Advanced Settings > Register Callback > UART to
 *     ENABLE (the Logger uses HAL_UART_RegisterCallback()).
 *  4. Give every pin the same User Label as on the previous board.
 *  5. Copy Application/, Peripheral/, Services/, this file and the main.c
 *     USER CODE contents, and add Application/Inc, Peripheral/Inc and
 *     Services/Inc to the include paths.
 *  6. Edit this file only: the device check, SEB_BOARD_NAME and every
 *     SEB_BOARD_* mapping.
 * No SEB module changes when porting.
 */

#ifndef BOARD_CONFIG_H
#define BOARD_CONFIG_H

/*
 * The values below belong to one device. Building for any other device
 * stops here, so a port cannot silently use this board's handles.
 */
#if !defined(STM32F303xC)
#error "board_config.h holds STM32F303VC values; update it for this device."
#else

/* CubeMX: HAL of the target family and the user-label pin defines. */
#include "main.h"

/** Board name, for diagnostics. */
#define SEB_BOARD_NAME          "STM32F303VC-POC"

/**
 * CubeMX-owned debug UART handle, defined in main.c: USART3, PB10 TX /
 * PB11 RX, 115200 8N1, interrupt-driven, no DMA.
 */
extern UART_HandleTypeDef huart3;

/** Debug UART used by the Logger. Interrupt-driven only, never DMA. */
#define SEB_BOARD_LOG_UART      (&huart3)

/**
 * CubeMX-owned Local UART handle, defined in main.c: USART2, PA2 TX /
 * PA3 RX, 19200 8N1, RX on DMA circular, TX interrupt-driven.
 */
extern UART_HandleTypeDef huart2;

/** UART to the local device (SBC on Main, RockBLOCK on Sub), section 3.2. */
#define SEB_BOARD_LOCAL_UART    (&huart2)

/*
 * Still to be added, by the module that first uses each one (architecture
 * sections 1.5.3 item 4 and 3.5): mode-select pin, address DIP switches
 * 1-3, SLP, NET, RI and Link UART. Their pins and instances are
 * TBD (architecture appendix item 25), so none is defined yet. Each is
 * added as a mapping to a CubeMX user label or handle, for example:
 *
 *     #define SEB_BOARD_MODE_SEL_PORT     MODE_SEL_GPIO_Port
 *     #define SEB_BOARD_MODE_SEL_PIN      MODE_SEL_Pin
 */

/*
 * CubeMX settings every board project must have. Checked here so that a
 * new project reports the missing setting by name.
 */
#if !defined(HAL_UART_MODULE_ENABLED)
#error "board_config: no UART is enabled in CubeMX. Enable the debug USART."
#endif

#if !defined(HAL_DMA_MODULE_ENABLED)
#error "board_config: no DMA is enabled in CubeMX. Add USART2_RX DMA (circular) for the Local UART."
#endif

#if !defined(USE_HAL_UART_REGISTER_CALLBACKS)
#error "board_config: set CubeMX Project Manager > Advanced Settings > Register Callback > UART to ENABLE."
#elif (USE_HAL_UART_REGISTER_CALLBACKS != 1U)
#error "board_config: set CubeMX Project Manager > Advanced Settings > Register Callback > UART to ENABLE."
#endif

#endif /* STM32F303xC */

#endif /* BOARD_CONFIG_H */
